FROM tb_users u LEFT JOIN tb_user_identities i ON i.user_id = u.id AND i.provider = 'LOCAL' AND i.password_hash IS NOT NULL WHERE EXISTS ( SELECT 1 FROM tb_user_roles r WHERE r.user_id = u.id
AND r.role = #{criteria.role} AND r.role IN ('PLATFORM_ADMIN', 'INSTITUTION_ADMIN')
)
AND u.status = #{criteria.status}
AND ( LOWER(u.name) LIKE '%' || #{criteria.keyword} || '%' ESCAPE '\' OR LOWER(u.email) LIKE '%' || #{criteria.keyword} || '%' ESCAPE '\' )

mapper.select:

SELECT 

 ORDER BY u.created_at DESC, u.id ASC
 LIMIT #{criteria.limit} OFFSET #{criteria.offset}
